-- Cogni v0.7.0: mixed interaction formats, balanced MCQs, and adaptive daily lessons.

alter table public.challenges add column if not exists interaction_type text not null default 'single_choice';
alter table public.challenges add column if not exists interaction_config jsonb not null default '{}'::jsonb;
do $$ begin alter table public.challenges add constraint challenges_interaction_type_check check (interaction_type in ('single_choice','multi_select','ranking','classification','triage')); exception when duplicate_object then null; end $$;
alter table public.challenge_answer_keys alter column correct_index drop not null;
alter table public.challenge_answer_keys add column if not exists correct_answer jsonb;
update public.challenge_answer_keys set correct_answer=to_jsonb(correct_index) where correct_answer is null and correct_index is not null;
alter table public.user_responses add column if not exists response_payload jsonb;
alter table public.user_responses add column if not exists score_fraction numeric(5,4) check (score_fraction between 0 and 1);
update public.user_responses set score_fraction=case when is_correct then 1 else 0 end where score_fraction is null;
alter table public.user_responses alter column score_fraction set default 0;
alter table public.user_responses alter column score_fraction set not null;
create table if not exists public.daily_lessons (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, subtitle text not null, emoji text not null default '🧠', skill_id uuid references public.skills(id) on delete set null, content jsonb not null default '{}'::jsonb, estimated_minutes integer not null default 3 check (estimated_minutes between 1 and 10), is_published boolean not null default true, sort_order integer not null default 1000, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.user_lesson_completions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, lesson_id uuid not null references public.daily_lessons(id) on delete cascade, lesson_date date not null, completed_at timestamptz not null default now(), unique(user_id,lesson_date));
alter table public.training_sessions add column if not exists lesson_id uuid references public.daily_lessons(id) on delete set null;
alter table public.daily_lessons enable row level security;
alter table public.user_lesson_completions enable row level security;
drop policy if exists "published lessons readable" on public.daily_lessons;
create policy "published lessons readable" on public.daily_lessons for select to authenticated using(is_published=true);
drop policy if exists "own lesson completions readable" on public.user_lesson_completions;
create policy "own lesson completions readable" on public.user_lesson_completions for select to authenticated using(user_id=auth.uid());
create index if not exists idx_lessons_skill on public.daily_lessons(skill_id,is_published,sort_order);
create index if not exists idx_lesson_completions_user_date on public.user_lesson_completions(user_id,lesson_date desc);

