-- Seed one short, story-led lesson for every judgement capability.

insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('aed4d215-356d-5503-be4f-416a18111e7c','critical-thinking','The confident memo','Confidence is not a checksum','🕵️','55f6fc56-0a05-5326-b3cb-3c15da2a86f6','{"story": "A polished recommendation lands in your inbox: “Option B is clearly best.” It has headings, tables and a decisive conclusion. Your brain wants to relax because it looks finished.", "twist": "The surprise: presentation quality and reasoning quality can move independently. A beautiful answer can still rest on one weak assumption.", "principle": "Before judging the conclusion, inspect the chain: claim → evidence → assumptions → alternatives.", "try_it": "Imagine the same memo with all branding removed. What single sentence would you challenge first?", "reveal": "Start with the sentence carrying the most decision weight, then ask what evidence would make it false.", "ai_age": "AI makes fluent answers cheap. Your edge is inspecting the reasoning underneath the fluency."}'::jsonb,3,true,1) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('9124f382-a938-57da-bf0b-dd10ccce85d4','ai-output-verification','The citation that never existed','AI can sound sourced without being sourceable','📚','c5d12144-0ec8-5b8d-a68e-b1830e4dbb72','{"story": "An AI assistant gives you a perfect-looking policy answer and cites “Section 14.3”. You search the document. There is no Section 14.3.", "twist": "The useful habit is not “never trust AI”. It is matching verification effort to the claim and the stakes.", "principle": "Treat citations, numbers, quotes and contractual claims as verification triggers.", "try_it": "Which would you verify first: a writing suggestion, a lunch recommendation, or a £2m contractual liability claim?", "reveal": "The contractual claim. Verification priority should rise with consequence and irreversibility.", "ai_age": "Use AI to accelerate search and synthesis, but verify the facts that carry the decision."}'::jsonb,3,true,2) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('785cabd8-7cfa-5aec-b958-ad329bbf2300','evidence-evaluation','Four witnesses, one decision','Not all evidence deserves equal weight','⚖️','2f70ee86-15d9-5d3c-9e3d-6ac2bcb7faf5','{"story": "Four people tell you a new process “works”: the vendor, a senior sponsor, three users, and an independent controlled comparison.", "twist": "The loudest witness is not necessarily the strongest. Independence, measurement quality and alternative explanations matter.", "principle": "Prefer evidence that directly tests the claim and survives plausible competing explanations.", "try_it": "If you could keep only one of the four evidence sources, which would you keep and why?", "reveal": "Usually the independent controlled comparison—if its design and data are credible—because it directly tests the claim.", "ai_age": "AI can summarise twenty weak sources into one persuasive paragraph. Quantity does not automatically become quality."}'::jsonb,3,true,3) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('56c43f60-ce4f-5c28-8243-092f29f055d6','logical-reasoning','Wet streets and backwards logic','A true conclusion can still come from bad reasoning','🌧️','7342926e-94ad-58c3-800d-1082188635c1','{"story": "If it rains, the street gets wet. The street is wet. Did it definitely rain? Not necessarily—a street cleaner could have passed.", "twist": "This is why “the conclusion happened” does not prove the reasoning that predicted it was valid.", "principle": "Check whether the conclusion follows necessarily, probably, or not at all from the premises.", "try_it": "Think of one other cause of a wet street besides rain.", "reveal": "A sprinkler, cleaning truck, burst pipe—or several others. Alternative causes break the inference.", "ai_age": "AI often compresses several reasoning steps into one confident sentence. Expand the steps and test each link."}'::jsonb,3,true,4) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('edbf252e-8f64-506c-9015-51a8e2b86bdb','bias-recognition','The planes that came home','The missing data may matter more than the visible data','✈️','0d49b8d0-94b1-597b-b3f1-ff7e746bdb0a','{"story": "In the classic WWII survivorship-bias story, analysts mapped bullet holes on returning aircraft. The tempting move was to reinforce the most damaged areas.", "twist": "But the planes that returned showed where damage was survivable. The missing planes were the crucial data.", "principle": "Ask: what am I not seeing because it failed, dropped out, was filtered or never reported?", "try_it": "Where could survivorship bias appear in a list of “successful AI projects”?", "reveal": "Failed pilots may never become case studies, so published success stories can overstate the true hit rate.", "ai_age": "AI training data and online examples can overrepresent visible successes. Search deliberately for the missing failures."}'::jsonb,3,true,5) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('eb9516b5-ed86-5933-b70e-e621e3a137e9','decision-uncertainty','Would you launch at 70%?','Good decisions do not require fake certainty','🎯','62ca3385-246b-5830-89d9-9c3d4a1947e4','{"story": "You have a reversible pilot with modest downside and 70% confidence it will help. Waiting three months could raise confidence to 85%, but costs time.", "twist": "The right threshold depends on reversibility, downside, upside and the value of more information—not a universal confidence number.", "principle": "Match the amount of evidence required to the cost of being wrong and the ease of reversing course.", "try_it": "Would you demand the same certainty for a two-week pilot as for deleting the only copy of a database?", "reveal": "No. The irreversible action deserves a dramatically higher evidence threshold.", "ai_age": "AI can provide probabilities, but humans still need to decide what level of uncertainty is acceptable for the stakes."}'::jsonb,3,true,6) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('619544b0-32de-5e8f-baff-8250153ae98f','problem-framing','“We need an AI tool” — do we?','Solutions often arrive disguised as problems','🧩','725d15f2-56f3-5fda-b9fe-e65fa20168f2','{"story": "A team says: “Our problem is that we do not have an AI assistant.” That is already a proposed solution.", "twist": "A better frame might be: “People spend six hours a week finding and rewriting the same information.” Now multiple solutions become possible.", "principle": "Frame the undesirable outcome before choosing the mechanism.", "try_it": "Rewrite “We need a chatbot” as a problem statement without naming any technology.", "reveal": "Example: “Employees cannot get reliable answers to policy questions quickly enough.”", "ai_age": "AI is powerful, but starting with AI can make you automate the wrong problem beautifully."}'::jsonb,3,true,7) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('97832831-9868-555f-88c3-23463b0d842c','assumption-identification','The forecast with invisible scaffolding','Every forecast is standing on assumptions','🏗️','04ac8495-66ab-50a7-95e0-0a6ea1cd1d00','{"story": "A project forecast says completion will move forward by three weeks if weekend shifts are added.", "twist": "Hidden underneath: labour is available, productivity holds, approvals keep pace, rework does not rise, and dependencies cooperate.", "principle": "Ask what must be true for the conclusion to hold.", "try_it": "Name one assumption that could make “more people = faster delivery” fail.", "reveal": "Coordination overhead, constrained workspace, skill mismatch or bottlenecks can make extra people add less speed than expected.", "ai_age": "AI forecasts often present outputs more clearly than assumptions. Make the assumptions visible before acting."}'::jsonb,3,true,8) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('5461b4f2-eda5-5876-9bcb-cc552ae19dfd','correlation-causation','Ice cream predicts drowning?','Two things moving together is a clue, not a cause','🍦','7e039899-fc7a-5bd6-b06d-13c9eac577f5','{"story": "Ice-cream sales and drownings both rise in summer. Buying ice cream does not cause drowning; hot weather pushes both upward.", "twist": "A correlation can be real and still be useless as a causal explanation.", "principle": "Before saying “X caused Y”, test reverse causality, common causes, selection effects and coincidence.", "try_it": "If AI adoption and productivity both rose this quarter, what else might explain both?", "reveal": "A new manager, seasonal demand, staffing changes, process redesign or measurement changes could affect both.", "ai_age": "AI can spot patterns quickly. Human judgement is needed to decide whether the pattern has a credible causal story."}'::jsonb,3,true,9) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('41b5088e-a2b1-5a83-9ba4-608f4b3b931a','source-quality','Screenshot, spreadsheet, source','Provenance beats polish','🔎','c3a75d64-fbae-5044-ae49-252bf3718af7','{"story": "You receive three versions of the same number: a screenshot in chat, a spreadsheet forwarded twice, and the original system report.", "twist": "The number may match in all three, but provenance changes how confidently you can rely on it.", "principle": "Prefer sources that are primary, current, attributable and independently checkable.", "try_it": "What question upgrades a screenshot from “interesting” to “decision-grade”?", "reveal": "Ask where it came from, when it was produced, who owns it and whether the underlying source can be opened.", "ai_age": "When AI quotes a statistic, follow the chain back to the original evidence rather than trusting the summary layer."}'::jsonb,3,true,10) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('c3236961-7035-5bfd-bcec-0efca22befe9','hallucination-detection','The invented clause','Specificity can be a warning sign, not proof','👻','9484e8fc-32d6-58c2-a6f8-0fee42f4ebd7','{"story": "An AI response quotes a precise contract clause with a section number and confident wording. The clause is not in the contract.", "twist": "Hallucinations can look more convincing because they are specific. Precision is not provenance.", "principle": "Verify exact quotes, references, numbers and named authorities against the source.", "try_it": "What is safer: “I cannot find the clause” or inventing the most likely clause from similar contracts?", "reveal": "“I cannot find it.” Uncertainty stated clearly is safer than fabricated precision.", "ai_age": "Good AI use includes knowing when the model should retrieve, cite, abstain or hand off to a human."}'::jsonb,3,true,11) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('f8368172-c7c6-5270-83d4-d3351f0abfe3','missing-information','“Sales doubled!”','A percentage without a denominator can mislead','📈','811d4c6e-fa62-596b-bdb4-9bbe3686ed2d','{"story": "A headline says sales doubled. That sounds huge—until you learn they rose from 2 units to 4.", "twist": "Missing context can turn a technically true statement into a bad decision signal.", "principle": "Ask for denominator, baseline, time period, sample, comparison group and materiality.", "try_it": "What is the first missing number you would ask for after hearing “complaints fell 50%”?", "reveal": "The original complaint count. Falling from 2 to 1 means something different from 2,000 to 1,000.", "ai_age": "AI summaries often compress away denominators and caveats. Reconstruct the context before relying on the headline."}'::jsonb,3,true,12) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('6749b20a-6512-5ae2-b8e1-9a81bd2b6e08','argument-comparison','Two brilliant pitches','Compare arguments on the same scoreboard','🥊','27c3086c-1cb6-5695-ad57-139002ab13db','{"story": "Two proposals are both persuasive. One has stronger evidence but modest upside; the other has exciting upside but weak evidence.", "twist": "People often compare the best feature of one argument with the worst feature of the other.", "principle": "Use common criteria: evidence quality, assumptions, downside, reversibility and expected value.", "try_it": "Pick two criteria you would use to compare competing AI proposals fairly.", "reveal": "For example: evidence that the benefit is real, and downside if the proposal fails.", "ai_age": "AI can generate convincing arguments for both sides. A shared evaluation rubric prevents rhetoric from winning by default."}'::jsonb,3,true,13) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('f4641962-1057-51f1-b398-ef0071651187','better-questions','The question that changes the answer','Great questions reduce uncertainty, not just collect facts','❓','aa9185f2-51d7-5072-8511-7413dcaa58c6','{"story": "“Do users like the tool?” may produce reassuring opinions. “What task takes less time, by how much, and compared with what baseline?” changes the decision.", "twist": "A high-value question targets the uncertainty that could change what you do next.", "principle": "Ask questions with decision impact: What would change my mind? What evidence is missing? What alternative explanation survives?", "try_it": "Turn “Is this AI accurate?” into a more decision-useful question.", "reveal": "Example: “On the tasks where an error would matter, what is the measured error rate and how was it independently checked?”", "ai_age": "Prompt quality matters, but judgement quality matters more: ask questions that expose uncertainty rather than merely improve wording."}'::jsonb,3,true,14) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.daily_lessons(id,slug,title,subtitle,emoji,skill_id,content,estimated_minutes,is_published,sort_order) values ('88236c5a-faf5-58ce-a8b2-baad39f291d5','ai-trust-boundaries','When the stakes change the rules','The same AI answer can be fine in one context and reckless in another','🚦','8750eb1c-de35-5e11-909d-d35ae5b29033','{"story": "AI suggests a dinner recipe and later suggests how to interpret a contractual liability clause. Both answers sound equally fluent.", "twist": "Trust should not be based only on model confidence or writing quality. Stakes, reversibility and verifiability change the required human oversight.", "principle": "Increase verification as consequences become larger, harder to reverse or more safety-critical.", "try_it": "Which needs more human checking: a meeting title or a payroll instruction affecting 2,000 people?", "reveal": "The payroll instruction. The downside and scale raise the verification threshold.", "ai_age": "The goal is not “trust AI” or “never trust AI”. It is knowing where AI sits inside an appropriate control system."}'::jsonb,3,true,15) on conflict(slug) do update set title=excluded.title,subtitle=excluded.subtitle,emoji=excluded.emoji,skill_id=excluded.skill_id,content=excluded.content,estimated_minutes=excluded.estimated_minutes,is_published=excluded.is_published,sort_order=excluded.sort_order;

-- Seed 30 non-standard interactions: multi-select, ranking, classification, and scenario triage.

insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('0a5616a4-b503-5da4-b93c-b9150aa5f66a','Audit the AI board note','An AI summary recommends approving a supplier immediately. Select every issue that should trigger verification before approval.','["The supplier performance figures are uncited.", "The recommendation contains a semicolon.", "The summary assumes last year’s performance predicts this project.", "The answer gives no indication of data freshness."]'::jsonb,'ai_answer_audit','multi_select','{"instructions": "Select every option that applies. There may be more than one correct answer."}'::jsonb,58,false,true,'general',true,201) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('0a5616a4-b503-5da4-b93c-b9150aa5f66a',null,'[0, 2, 3]'::jsonb,'Uncited figures, an unstated predictive assumption and unknown data freshness all weaken the recommendation. Punctuation does not.','Audit the evidence chain, assumptions and freshness—not cosmetic features.','Before acting on AI output, verify the facts and assumptions carrying the decision.','{"default": "evidence_neglect"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('0a5616a4-b503-5da4-b93c-b9150aa5f66a','c5d12144-0ec8-5b8d-a68e-b1830e4dbb72',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('6741b346-a08c-57c1-b84c-8a95c317b83c','Spot the source-quality red flags','You receive a statistic in a slide deck. Select every feature that lowers confidence in the source.','["It links to the original published dataset.", "The screenshot has no date.", "The number was forwarded through three people with no owner.", "A methodology note explains how the measure was produced."]'::jsonb,'source_audit','multi_select','{"instructions": "Select every option that applies. There may be more than one correct answer."}'::jsonb,48,false,true,'general',true,202) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('6741b346-a08c-57c1-b84c-8a95c317b83c',null,'[1, 2]'::jsonb,'Missing date and unclear provenance are source-quality problems; original data and methodology improve confidence.','Trace evidence back to a current, attributable, checkable source.','AI summaries should lead you toward provenance, not replace it.','{"default": "authority_bias"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('6741b346-a08c-57c1-b84c-8a95c317b83c','c3a75d64-fbae-5044-ae49-252bf3718af7',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('dc311213-454a-5e2b-b3f2-b1c54c1060af','What else could explain the pattern?','Productivity rose after an AI rollout. Select every plausible alternative explanation that should be checked before claiming the AI caused the increase.','["A seasonal demand shift changed the work mix.", "A process redesign launched at the same time.", "The chart uses the same font before and after.", "Low-performing teams were excluded from the post-rollout sample."]'::jsonb,'causal_audit','multi_select','{"instructions": "Select every option that applies. There may be more than one correct answer."}'::jsonb,62,false,true,'general',true,203) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('dc311213-454a-5e2b-b3f2-b1c54c1060af',null,'[0, 1, 3]'::jsonb,'Seasonality, concurrent changes and sample selection can all create or exaggerate the apparent effect.','A causal claim must survive plausible alternative explanations.','Treat AI-detected correlations as hypotheses until competing causes are tested.','{"default": "causal_overreach"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('dc311213-454a-5e2b-b3f2-b1c54c1060af','7e039899-fc7a-5bd6-b06d-13c9eac577f5',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('0bfc6616-1273-5532-9091-dcd63c2105cf','Find the invisible assumptions','A plan says “automating approvals will cut cycle time by 40%.” Select every assumption that must be tested.','["Approvals are a major current bottleneck.", "Automated decisions will not create extra rework.", "The slide uses company colours.", "Users will route cases through the automated path."]'::jsonb,'assumption_audit','multi_select','{"instructions": "Select every option that applies. There may be more than one correct answer."}'::jsonb,55,false,true,'general',true,204) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('0bfc6616-1273-5532-9091-dcd63c2105cf',null,'[0, 1, 3]'::jsonb,'The benefit depends on the bottleneck, rework and adoption assumptions—not the slide design.','Ask what must be true for the forecast to work.','AI business cases often hide assumptions inside precise-looking benefit estimates.','{"default": "assumption_blindness"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('0bfc6616-1273-5532-9091-dcd63c2105cf','04ac8495-66ab-50a7-95e0-0a6ea1cd1d00',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('b85fe539-dfaf-55af-bfd9-df4dd0f1cb10','What is missing before you decide?','A dashboard says customer complaints fell 50% after a change. Select every missing fact you would want before crediting the change.','["The original complaint count.", "Whether complaint definitions changed.", "A relevant comparison or baseline period.", "The colour used for the dashboard line."]'::jsonb,'missing_info_audit','multi_select','{"instructions": "Select every option that applies. There may be more than one correct answer."}'::jsonb,50,false,true,'general',true,205) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('b85fe539-dfaf-55af-bfd9-df4dd0f1cb10',null,'[0, 1, 2]'::jsonb,'The denominator, measurement definition and comparison context determine whether the headline means what it appears to mean.','A percentage without context is not decision-grade evidence.','Ask AI to expose the denominator, baseline and measurement changes behind summary statistics.','{"default": "missing_denominator"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('b85fe539-dfaf-55af-bfd9-df4dd0f1cb10','811d4c6e-fa62-596b-bdb4-9bbe3686ed2d',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('08893ffe-e02d-58af-9c67-21587b57975e','Verify the suspicious specifics','An AI answer contains several precise claims. Select every item that deserves direct source verification.','["An exact quotation from a contract.", "A named court case and citation.", "A suggestion to make the paragraph shorter.", "A claimed statutory deadline."]'::jsonb,'hallucination_audit','multi_select','{"instructions": "Select every option that applies. There may be more than one correct answer."}'::jsonb,64,false,true,'general',true,206) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('08893ffe-e02d-58af-9c67-21587b57975e',null,'[0, 1, 3]'::jsonb,'Quotes, citations and legal deadlines are factual specifics with real consequences; they should be checked against authoritative sources.','Specificity is not proof. Verify consequential details at source.','Use retrieval and citations for high-stakes factual claims, and allow the model to abstain when evidence is unavailable.','{"default": "hallucination_acceptance"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('08893ffe-e02d-58af-9c67-21587b57975e','9484e8fc-32d6-58c2-a6f8-0fee42f4ebd7',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('7e701128-e22d-5813-b53e-217d27cc333d','Which evidence actually helps?','A team claims a new process reduces defects. Select every item that materially strengthens the claim.','["A controlled before/after comparison using the same defect definition.", "A sponsor says the team feels more confident.", "Independent replication on a second project.", "A vendor brochure says similar clients improved."]'::jsonb,'evidence_audit','multi_select','{"instructions": "Select every option that applies. There may be more than one correct answer."}'::jsonb,60,false,true,'general',true,207) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('7e701128-e22d-5813-b53e-217d27cc333d',null,'[0, 2]'::jsonb,'Controlled measurement and independent replication directly strengthen the claim. Sponsor sentiment and vendor marketing are weaker evidence.','Prefer evidence that directly tests the claim and reduces alternative explanations.','Ask AI to rank evidence by relevance, independence and design quality—not by how persuasive it sounds.','{"default": "evidence_neglect"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('7e701128-e22d-5813-b53e-217d27cc333d','2f70ee86-15d9-5d3c-9e3d-6ac2bcb7faf5',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('177a6ab2-621b-51b6-a25a-79e51e90eb51','Catch the premature conclusion','A recommendation says “the pilot succeeded, so we should scale immediately.” Select every question that challenges premature closure.','["What failed or degraded during the pilot?", "How representative was the pilot population?", "Can the logo be made larger?", "What conditions would make scaling fail?"]'::jsonb,'critical_audit','multi_select','{"instructions": "Select every option that applies. There may be more than one correct answer."}'::jsonb,57,false,true,'general',true,208) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('177a6ab2-621b-51b6-a25a-79e51e90eb51',null,'[0, 1, 3]'::jsonb,'Failure modes, representativeness and scaling conditions all test whether the conclusion travels beyond the pilot.','Before closing a decision, search for disconfirming evidence and boundary conditions.','AI can accelerate a conclusion; your job is to slow down at the point where assumptions become action.','{"default": "premature_closure"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('177a6ab2-621b-51b6-a25a-79e51e90eb51','55f6fc56-0a05-5326-b3cb-3c15da2a86f6',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('34e1074c-547a-5b41-9e05-b381b69a6631','Rank these sources','Rank the four sources from strongest to weakest for deciding whether a regulation changed.','["A colleague’s memory of the rule.", "The regulator’s current official publication.", "A law-firm blog summarising the update.", "An anonymous social-media post."]'::jsonb,'source_ranking','ranking','{"instructions": "Tap the cards in order. Tap a ranked card to remove it and try again."}'::jsonb,52,false,true,'general',true,209) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('34e1074c-547a-5b41-9e05-b381b69a6631',null,'[1, 2, 0, 3]'::jsonb,'The regulator’s current publication is primary and authoritative; a reputable secondary summary comes next, then memory, then anonymous social media.','Rank sources by authority, proximity to the original evidence, currency and checkability.','When AI cites secondary commentary, follow the chain to the primary source where possible.','{"default": "source_quality_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('34e1074c-547a-5b41-9e05-b381b69a6631','c3a75d64-fbae-5044-ae49-252bf3718af7',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('9ee9c568-76f7-5a5f-b4d5-15de8e92100d','Rank the questions by decision value','A pilot looks promising but you are unsure whether to scale. Rank these questions from most to least useful for reducing decision uncertainty.','["What colour should the launch deck use?", "What evidence would show the pilot effect does not generalise?", "How did the measured benefit compare with a credible baseline?", "Did people enjoy the demo?"]'::jsonb,'question_ranking','ranking','{"instructions": "Tap the cards in order. Tap a ranked card to remove it and try again."}'::jsonb,56,false,true,'general',true,210) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('9ee9c568-76f7-5a5f-b4d5-15de8e92100d',null,'[2, 1, 3, 0]'::jsonb,'Baseline impact and generalisability can change the decision. Enjoyment may add context; deck colour adds almost none.','Prioritise questions by how much they can change the decision.','Use AI to generate questions, then rank them by uncertainty reduction rather than novelty.','{"default": "low_value_question"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('9ee9c568-76f7-5a5f-b4d5-15de8e92100d','aa9185f2-51d7-5072-8511-7413dcaa58c6',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('13b2c7ee-8279-506e-91fd-ca64187c4f3f','Rank the causal evidence','Rank these from strongest to weakest evidence that a training programme caused better performance.','["A randomised comparison shows a persistent difference.", "Performance rose after training with no comparison group.", "High performers report liking the training.", "A manager says the programme “must have helped”."]'::jsonb,'causal_ranking','ranking','{"instructions": "Tap the cards in order. Tap a ranked card to remove it and try again."}'::jsonb,68,false,true,'general',true,211) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('13b2c7ee-8279-506e-91fd-ca64187c4f3f',null,'[0, 1, 2, 3]'::jsonb,'Randomisation best addresses competing explanations. A simple before/after pattern is weaker; preference and managerial belief are weaker still.','Causal confidence rises as the design eliminates alternative explanations.','AI can discover associations; causal confidence depends on study design, not verbal certainty.','{"default": "causal_overreach"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('13b2c7ee-8279-506e-91fd-ca64187c4f3f','7e039899-fc7a-5bd6-b06d-13c9eac577f5',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('eba9c56d-b8e3-5ecd-8cc8-a6e51e6cf285','Rank by verification need','Rank these AI uses from highest to lowest need for human verification.','["Drafting a meeting title.", "Interpreting a safety-critical operating instruction.", "Suggesting three lunch options.", "Calculating a contractual payment obligation from uploaded terms."]'::jsonb,'risk_ranking','ranking','{"instructions": "Tap the cards in order. Tap a ranked card to remove it and try again."}'::jsonb,58,false,true,'general',true,212) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('eba9c56d-b8e3-5ecd-8cc8-a6e51e6cf285',null,'[1, 3, 0, 2]'::jsonb,'Safety-critical and contractual decisions carry high downside; meeting titles and lunch suggestions are low stakes and reversible.','Verification effort should scale with consequence, irreversibility and uncertainty.','Place AI inside stronger controls as stakes rise.','{"default": "trust_boundary_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('eba9c56d-b8e3-5ecd-8cc8-a6e51e6cf285','8750eb1c-de35-5e11-909d-d35ae5b29033',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('37943045-eb2c-5e2b-9a2b-8332ba6511a0','Rank the actions by reversibility','Rank these decisions from easiest to hardest to reverse.','["Run a two-week pilot with a rollback plan.", "Send a draft internally for review.", "Migrate the only production dataset with no backup.", "Change a preference setting that can be restored instantly."]'::jsonb,'reversibility_ranking','ranking','{"instructions": "Tap the cards in order. Tap a ranked card to remove it and try again."}'::jsonb,48,false,true,'general',true,213) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('37943045-eb2c-5e2b-9a2b-8332ba6511a0',null,'[3, 1, 0, 2]'::jsonb,'A reversible preference change is easiest, followed by an internal draft, then a pilot; an unbacked production migration is hardest to reverse.','Reversibility should influence how much evidence you demand before acting.','When AI recommends action, ask how costly it would be to undo if the recommendation is wrong.','{"default": "uncertainty_miscalibration"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('37943045-eb2c-5e2b-9a2b-8332ba6511a0','62ca3385-246b-5830-89d9-9c3d4a1947e4',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('9518a4d3-e08b-5427-b9d4-40342a99e85c','Rank the proposals','Rank the proposals from strongest to weakest based on evidential support.','["Large benefit claim backed only by a vendor testimonial.", "Moderate benefit supported by replicated internal measurements.", "Huge benefit inferred from one anecdote.", "Small benefit supported by a well-designed controlled test."]'::jsonb,'argument_ranking','ranking','{"instructions": "Tap the cards in order. Tap a ranked card to remove it and try again."}'::jsonb,61,false,true,'general',true,214) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('9518a4d3-e08b-5427-b9d4-40342a99e85c',null,'[1, 3, 0, 2]'::jsonb,'Replicated internal measurements and a controlled test provide the strongest support. Large claims do not compensate for weak evidence.','Compare arguments using the same criteria, especially evidence quality and uncertainty.','AI can make all four proposals sound compelling; use an explicit evidence rubric.','{"default": "argument_weighting_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('9518a4d3-e08b-5427-b9d4-40342a99e85c','27c3086c-1cb6-5695-ad57-139002ab13db',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('06ac1809-364e-5893-a9aa-c9bed5f65ec7','Rank the inference strength','Rank these statements from strongest to weakest logical support for “the system caused the outage”.','["The outage began immediately after the system change and disappeared when the change was rolled back, twice.", "The outage happened on the same day as the change.", "Someone predicted the change would be risky.", "The system name appears in an unrelated warning log."]'::jsonb,'inference_ranking','ranking','{"instructions": "Tap the cards in order. Tap a ranked card to remove it and try again."}'::jsonb,66,false,true,'general',true,215) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('06ac1809-364e-5893-a9aa-c9bed5f65ec7',null,'[0, 1, 2, 3]'::jsonb,'Repeated onset and reversal is much stronger evidence than timing alone; prediction and unrelated log mentions add little.','Separate evidence that discriminates between explanations from evidence that merely sounds relevant.','Ask AI to show which observations would differ if an alternative explanation were true.','{"default": "invalid_inference"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('06ac1809-364e-5893-a9aa-c9bed5f65ec7','7342926e-94ad-58c3-800d-1082188635c1',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('2501d810-d5bf-5e7b-8444-2bf9143bc08a','Rank the problem statements','Rank these from best to worst framed for action.','["Staff spend six hours a week searching for approved policy answers, causing delays and rework.", "We need a chatbot.", "Technology is bad.", "People should work faster."]'::jsonb,'framing_ranking','ranking','{"instructions": "Tap the cards in order. Tap a ranked card to remove it and try again."}'::jsonb,46,false,true,'general',true,216) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('2501d810-d5bf-5e7b-8444-2bf9143bc08a',null,'[0, 1, 3, 2]'::jsonb,'The first describes an observable outcome and impact without locking in a solution. “We need a chatbot” is a solution statement; the others are vague.','Frame the undesirable outcome before choosing the mechanism.','Do not let AI solution ideas substitute for a clear problem definition.','{"default": "solutioneering"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('2501d810-d5bf-5e7b-8444-2bf9143bc08a','725d15f2-56f3-5fda-b9fe-e65fa20168f2',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('ff523edd-f888-50ce-83d7-2f43a122990c','Evidence or assumption?','Classify each statement in the forecast as evidence or assumption.','["Last quarter’s measured cycle time was 12 days.", "Users will adopt the new workflow immediately.", "The pilot processed 840 cases.", "Error rates will remain unchanged at scale."]'::jsonb,'evidence_assumption_sort','classification','{"categories": [{"id": "evidence", "label": "Evidence"}, {"id": "assumption", "label": "Assumption"}], "instructions": "Assign every statement to a category."}'::jsonb,50,false,true,'general',true,217) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('ff523edd-f888-50ce-83d7-2f43a122990c',null,'{"0": "evidence", "1": "assumption", "2": "evidence", "3": "assumption"}'::jsonb,'Measured historical observations are evidence; future dependencies stated as if certain are assumptions.','Label what is observed separately from what must be true.','AI-generated plans often blend evidence and assumptions into the same prose. Separate them before evaluation.','{"default": "assumption_blindness"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('ff523edd-f888-50ce-83d7-2f43a122990c','04ac8495-66ab-50a7-95e0-0a6ea1cd1d00',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('bb18932a-0d1c-5569-90a4-cc4405a65798','Claim, evidence or inference?','Classify each sentence by its role in the argument.','["Support tickets fell from 420 to 280 after launch.", "The new assistant improved service quality.", "Because ticket volume fell, the assistant probably reduced avoidable questions.", "The team should expand the assistant next quarter."]'::jsonb,'argument_structure_sort','classification','{"categories": [{"id": "claim", "label": "Claim"}, {"id": "evidence", "label": "Evidence"}, {"id": "inference", "label": "Inference"}], "instructions": "Assign every statement to a category."}'::jsonb,58,false,true,'general',true,218) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('bb18932a-0d1c-5569-90a4-cc4405a65798',null,'{"0": "evidence", "1": "claim", "2": "inference", "3": "claim"}'::jsonb,'The measured change is evidence; the causal bridge is an inference; the performance and action statements are claims.','Arguments become easier to audit when claims, evidence and inference are separated.','Ask AI to label its own evidence and inference rather than presenting one seamless answer.','{"default": "invalid_inference"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('bb18932a-0d1c-5569-90a4-cc4405a65798','7342926e-94ad-58c3-800d-1082188635c1',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('187706b5-986d-5772-a508-631bd778aade','Signal or noise?','Classify each detail by whether it should materially affect the decision.','["The measured effect disappears when one outlier is removed.", "The slide deck uses a new template.", "The sample excludes the highest-risk users.", "The presenter speaks confidently."]'::jsonb,'signal_noise_sort','classification','{"categories": [{"id": "signal", "label": "Signal"}, {"id": "noise", "label": "Noise"}], "instructions": "Assign every statement to a category."}'::jsonb,54,false,true,'general',true,219) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('187706b5-986d-5772-a508-631bd778aade',null,'{"0": "signal", "1": "noise", "2": "signal", "3": "noise"}'::jsonb,'Sensitivity to one outlier and sample exclusion can change the conclusion; template and confidence should not.','Weight information by decision relevance, not vividness.','AI can make irrelevant details salient. Keep attention on evidence that changes the conclusion.','{"default": "salience_bias"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('187706b5-986d-5772-a508-631bd778aade','55f6fc56-0a05-5326-b3cb-3c15da2a86f6',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('beb286d8-ad3d-53eb-a6f5-0973a82c7aac','Association or causal evidence?','Classify each observation.','["Teams using the tool are more productive, but they volunteered to adopt it.", "Random assignment to the tool produces a sustained productivity difference.", "Search interest and share price rose in the same month.", "The effect appears when treatment starts and disappears under a controlled withdrawal design."]'::jsonb,'causal_sort','classification','{"categories": [{"id": "association", "label": "Association only"}, {"id": "causal", "label": "Causal evidence"}], "instructions": "Assign every statement to a category."}'::jsonb,70,false,true,'general',true,220) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('beb286d8-ad3d-53eb-a6f5-0973a82c7aac',null,'{"0": "association", "1": "causal", "2": "association", "3": "causal"}'::jsonb,'Self-selection and co-movement show association; random assignment and controlled withdrawal provide stronger causal evidence.','Ask what design feature rules out alternative explanations.','AI can find association at scale; it cannot turn association into causation by wording it confidently.','{"default": "causal_overreach"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('beb286d8-ad3d-53eb-a6f5-0973a82c7aac','7e039899-fc7a-5bd6-b06d-13c9eac577f5',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('699919f6-9da0-53cb-bdb8-d33ba5efd502','Decision-grade or corroborate?','Classify each source for a high-stakes decision.','["Current regulator guidance on the regulator’s own website.", "An undated screenshot forwarded in chat.", "The signed contract stored in the document system.", "An AI answer with no citations."]'::jsonb,'source_grade_sort','classification','{"categories": [{"id": "decision_grade", "label": "Decision-grade"}, {"id": "corroborate", "label": "Needs corroboration"}], "instructions": "Assign every statement to a category."}'::jsonb,58,false,true,'general',true,221) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('699919f6-9da0-53cb-bdb8-d33ba5efd502',null,'{"0": "decision_grade", "1": "corroborate", "2": "decision_grade", "3": "corroborate"}'::jsonb,'Primary current sources can be decision-grade; screenshots and uncited AI output require corroboration.','Authority and provenance matter more as stakes rise.','Use AI as a navigation layer toward authoritative evidence, not as the final authority.','{"default": "source_quality_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('699919f6-9da0-53cb-bdb8-d33ba5efd502','c3a75d64-fbae-5044-ae49-252bf3718af7',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('8abe0d52-93af-5480-9a9a-3249cfc761ae','Verifiable or unsupported?','Classify the AI statements based on the evidence shown.','["“The contract says payment is due in 30 days” with a linked clause that opens correctly.", "“Industry best practice is 17.4%” with no source.", "“The policy was updated yesterday” with a timestamped official link.", "“Everyone agrees this is the safest option” with no evidence."]'::jsonb,'ai_claim_sort','classification','{"categories": [{"id": "verifiable", "label": "Verifiable fact"}, {"id": "unsupported", "label": "Unsupported claim"}], "instructions": "Assign every statement to a category."}'::jsonb,62,false,true,'general',true,222) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('8abe0d52-93af-5480-9a9a-3249cfc761ae',null,'{"0": "verifiable", "1": "unsupported", "2": "verifiable", "3": "unsupported"}'::jsonb,'Linked primary evidence makes the factual claims checkable; precise but uncited claims remain unsupported.','Check whether the claim can be traced to evidence, not whether it sounds plausible.','Require sources for consequential AI facts and let unsupported claims remain explicitly uncertain.','{"default": "hallucination_acceptance"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('8abe0d52-93af-5480-9a9a-3249cfc761ae','9484e8fc-32d6-58c2-a6f8-0fee42f4ebd7',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('591ef415-c7cb-539c-ace4-43a9cd976bf9','Known or still unknown?','A pilot report says “30 users saved 20 minutes per day.” Classify what is known versus still unknown.','["The reported sample size was 30 users.", "Whether the users were representative of the wider population.", "The reported time saving was 20 minutes per day.", "Whether quality or error rates changed."]'::jsonb,'known_unknown_sort','classification','{"categories": [{"id": "known", "label": "Known"}, {"id": "unknown", "label": "Still unknown"}], "instructions": "Assign every statement to a category."}'::jsonb,52,false,true,'general',true,223) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('591ef415-c7cb-539c-ace4-43a9cd976bf9',null,'{"0": "known", "1": "unknown", "2": "known", "3": "unknown"}'::jsonb,'The report gives sample size and claimed time saving, but representativeness and quality effects remain unknown.','List knowns and unknowns explicitly before turning a pilot into a general conclusion.','Ask AI to produce a missing-information register alongside its recommendation.','{"default": "missing_information"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('591ef415-c7cb-539c-ace4-43a9cd976bf9','811d4c6e-fa62-596b-bdb4-9bbe3686ed2d',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('be4fc4e4-24fa-59bf-94d7-43e0311b10b9','Bias risk or legitimate evidence?','Classify what should influence the decision.','["The first estimate you heard was £5m, so £4m now feels cheap.", "A controlled benchmark shows the market median is £3.2m.", "The sponsor is charismatic and senior.", "A sensitivity analysis shows the decision changes above £3.6m."]'::jsonb,'bias_sort','classification','{"categories": [{"id": "bias_risk", "label": "Bias risk"}, {"id": "legitimate", "label": "Legitimate evidence"}], "instructions": "Assign every statement to a category."}'::jsonb,56,false,true,'general',true,224) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('be4fc4e4-24fa-59bf-94d7-43e0311b10b9',null,'{"0": "bias_risk", "1": "legitimate", "2": "bias_risk", "3": "legitimate"}'::jsonb,'Anchoring and authority are bias risks; benchmark and sensitivity analysis provide decision-relevant evidence.','Notice when a feeling of plausibility comes from context rather than evidence.','AI may repeat anchors from prompts or prior text. Re-ground decisions in explicit evidence.','{"default": "anchoring"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('be4fc4e4-24fa-59bf-94d7-43e0311b10b9','0d49b8d0-94b1-597b-b3f1-ff7e746bdb0a',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('f050b29a-65bf-5fef-aa22-9212ab875af7','Payroll answer: what now?','AI gives a payroll instruction that would affect 2,000 employees but provides no source. What is the best next move?','["Use it now", "Verify against authoritative payroll/legal guidance", "Reject all future AI use"]'::jsonb,'trust_triage','triage','{"display": "decision_cards", "instructions": "Make the call you would make in the real situation."}'::jsonb,60,false,true,'general',true,225) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('f050b29a-65bf-5fef-aa22-9212ab875af7',1,to_jsonb(1),'The stakes are high, so verify against authoritative sources. The right response is stronger control, not blind trust or blanket rejection.','Match verification intensity to consequence and reversibility.','High-stakes AI outputs should be routed through authoritative evidence and human accountability.','{"default": "trust_boundary_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('f050b29a-65bf-5fef-aa22-9212ab875af7','8750eb1c-de35-5e11-909d-d35ae5b29033',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('8f5f5012-8161-580d-b1c6-d3fbf0dae524','A reversible pilot at 65% confidence','A two-week pilot has limited downside, a rollback plan and a 65% estimated chance of benefit. What is the strongest decision?','["Run the bounded pilot and measure outcomes", "Wait until certainty reaches 100%", "Scale to everyone immediately"]'::jsonb,'decision_triage','triage','{"display": "decision_cards", "instructions": "Make the call you would make in the real situation."}'::jsonb,52,false,true,'general',true,226) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('8f5f5012-8161-580d-b1c6-d3fbf0dae524',0,to_jsonb(0),'A bounded reversible pilot can be rational under uncertainty because downside is limited and the experiment creates information.','You do not need certainty when the action is reversible and informative.','Use AI estimates to structure experiments, not to manufacture false certainty.','{"default": "uncertainty_miscalibration"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('8f5f5012-8161-580d-b1c6-d3fbf0dae524','62ca3385-246b-5830-89d9-9c3d4a1947e4',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('8e51aaa9-cbca-5cd7-ac13-a677ac67bfb4','“We need a chatbot”','A stakeholder says the problem is “we need a chatbot.” What should you do first?','["Buy the highest-rated chatbot", "Reframe the underlying user problem and desired outcome", "Ask AI to write a chatbot business case"]'::jsonb,'framing_triage','triage','{"display": "decision_cards", "instructions": "Make the call you would make in the real situation."}'::jsonb,44,false,true,'general',true,227) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('8e51aaa9-cbca-5cd7-ac13-a677ac67bfb4',1,to_jsonb(1),'“We need a chatbot” is a solution statement. First identify the underlying outcome, friction and users affected.','Define the problem before locking in a mechanism.','AI should expand solution space after the problem is clear, not become the problem statement.','{"default": "solutioneering"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('8e51aaa9-cbca-5cd7-ac13-a677ac67bfb4','725d15f2-56f3-5fda-b9fe-e65fa20168f2',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('add50056-9f20-5394-ba5d-0afa93b7b162','Two persuasive proposals','Proposal A has stronger evidence; Proposal B has a larger claimed upside but relies on one anecdote. What is the best response?','["Choose B because the upside is larger", "Choose A automatically", "Compare both on common criteria and make uncertainty explicit"]'::jsonb,'argument_triage','triage','{"display": "decision_cards", "instructions": "Make the call you would make in the real situation."}'::jsonb,57,false,true,'general',true,228) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('add50056-9f20-5394-ba5d-0afa93b7b162',2,to_jsonb(2),'A fair comparison uses common criteria rather than one attractive feature. Stronger evidence matters, but so do downside, reversibility and expected value.','Use a shared decision rubric for competing arguments.','AI can advocate either side; force both onto the same evaluation framework.','{"default": "argument_weighting_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('add50056-9f20-5394-ba5d-0afa93b7b162','27c3086c-1cb6-5695-ad57-139002ab13db',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('34cb23d8-a824-5e8f-befd-e068a44ca556','The dashboard says “+35% efficiency”','You can ask one question before the steering meeting. Which question has the highest decision value?','["What font was used?", "Compared with what baseline, on which tasks, and how was the 35% measured?", "Can we make the number bigger on the slide?"]'::jsonb,'question_triage','triage','{"display": "decision_cards", "instructions": "Make the call you would make in the real situation."}'::jsonb,49,false,true,'general',true,229) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('34cb23d8-a824-5e8f-befd-e068a44ca556',1,to_jsonb(1),'The baseline, task scope and measurement method determine whether the headline is meaningful.','Ask the question most likely to change the decision.','Use AI to generate candidate questions, then prioritise by information value.','{"default": "low_value_question"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('34cb23d8-a824-5e8f-befd-e068a44ca556','aa9185f2-51d7-5072-8511-7413dcaa58c6',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('a67e35b6-348d-5e17-b223-01050d80263c','The vendor case study','A vendor case study reports 60% productivity gains at an unnamed client with no methodology. How should you treat it?','["As proof", "As a lead that needs independent corroboration", "As worthless under all circumstances"]'::jsonb,'evidence_triage','triage','{"display": "decision_cards", "instructions": "Make the call you would make in the real situation."}'::jsonb,46,false,true,'general',true,230) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,interaction_config=excluded.interaction_config,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('a67e35b6-348d-5e17-b223-01050d80263c',1,to_jsonb(1),'It is not proof, but it can still be a lead. The rational response is to seek independently checkable evidence.','Weak evidence can generate hypotheses without settling decisions.','Ask AI to distinguish evidence that suggests from evidence that demonstrates.','{"default": "evidence_neglect"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('a67e35b6-348d-5e17-b223-01050d80263c','2f70ee86-15d9-5d3c-9e3d-6ac2bcb7faf5',1.0) on conflict do nothing;

-- Additional story-led MCQs. Correct positions are deliberately balanced 5/5/5/5 across A–D.
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('8e9515a2-79f3-5e65-a909-60a4efcb6f49','The bullet-hole puzzle','You can reinforce only one part of WWII aircraft. Returning planes show many bullet holes in the wings but few around the engines. Where should you investigate first?','["The engine areas with few holes on returning planes", "The wings because they have the most visible holes", "Every area equally", "The tail because it is furthest from the pilot"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,56,false,true,'general',true,400) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('8e9515a2-79f3-5e65-a909-60a4efcb6f49',0,to_jsonb(0),'The missing aircraft matter: planes hit in critical engine areas may not have returned, so visible damage can mislead.','Look for missing cases, not just visible survivors.','AI case libraries can overrepresent successes and survivors; search for failed or absent cases.','{"1": "survivorship_bias", "2": "survivorship_bias", "3": "survivorship_bias"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('8e9515a2-79f3-5e65-a909-60a4efcb6f49','0d49b8d0-94b1-597b-b3f1-ff7e746bdb0a',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('b2532763-856a-5691-9d30-4dd6e3b7192b','The ice-cream mystery','A city finds that ice-cream sales and drownings rise together. What is the strongest first explanation to test?','["Ice cream makes people swim badly", "Hot weather increases both swimming and ice-cream buying", "Drowning causes people to buy ice cream", "The data must be fabricated"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,42,false,true,'general',true,401) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('b2532763-856a-5691-9d30-4dd6e3b7192b',1,to_jsonb(1),'A common cause—hot weather—can raise both variables without either causing the other.','Correlation is a clue; test common causes and reverse causality before claiming causation.','When AI spots a pattern, ask what third variable could drive both sides.','{"0": "causal_overreach", "2": "causal_overreach", "3": "causal_overreach"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('b2532763-856a-5691-9d30-4dd6e3b7192b','7e039899-fc7a-5bd6-b06d-13c9eac577f5',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('bf4c0504-d42b-5b6c-9974-bf57a8f297fe','The “200% growth” celebration','A product manager announces “usage grew 200% this week!” What number do you most need before celebrating?','["The number of slides in the presentation", "The manager’s confidence level", "The starting usage level", "The product logo colour"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,38,false,true,'general',true,402) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('bf4c0504-d42b-5b6c-9974-bf57a8f297fe',2,to_jsonb(2),'A 200% increase can be tiny or huge depending on the baseline.','Percentages need denominators and baselines.','Ask AI to surface the underlying counts behind impressive percentages.','{"0": "missing_denominator", "1": "missing_denominator", "3": "missing_denominator"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('bf4c0504-d42b-5b6c-9974-bf57a8f297fe','811d4c6e-fa62-596b-bdb4-9bbe3686ed2d',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('407c7e6d-31e7-59d3-a4d9-c1815674a678','The screenshot in the group chat','A screenshot claims a regulator changed a rule yesterday. What is the best next move?','["Forward the screenshot to more people", "Trust it because the screenshot looks authentic", "Ask whether the screenshot has many likes", "Open the regulator’s current official publication and verify the change"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,48,false,true,'general',true,403) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('407c7e6d-31e7-59d3-a4d9-c1815674a678',3,to_jsonb(3),'A primary current source is stronger than an unattributed screenshot.','Trace consequential claims back to authoritative, current sources.','Use AI to help locate the primary source, not to substitute for it.','{"0": "source_quality_error", "1": "source_quality_error", "2": "source_quality_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('407c7e6d-31e7-59d3-a4d9-c1815674a678','c3a75d64-fbae-5044-ae49-252bf3718af7',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('298345bd-4b27-5731-9482-69081e1d8249','The perfect-looking clause','AI quotes “Clause 14.3” from an uploaded contract, but you cannot find that clause. What should you do?','["Treat the quote as unverified and search the source directly", "Assume the contract parser missed it", "Use the quote if the wording sounds legal", "Ask the AI to make the quote more confident"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,63,false,true,'general',true,404) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('298345bd-4b27-5731-9482-69081e1d8249',0,to_jsonb(0),'The citation is not evidence unless it can be located in the source.','Exact quotes and references should be source-verifiable.','High-stakes AI claims need retrieval, citations and a safe way to abstain.','{"1": "hallucination_acceptance", "2": "hallucination_acceptance", "3": "hallucination_acceptance"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('298345bd-4b27-5731-9482-69081e1d8249','c5d12144-0ec8-5b8d-a68e-b1830e4dbb72',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('6abfe606-03ef-56ff-821f-fb9a07442a15','The cheap experiment','You are 65% confident a reversible two-week pilot will help. The downside is capped and measurement is ready. What is the strongest move?','["Wait for 100% certainty", "Run the bounded pilot and learn", "Scale to everyone immediately", "Abandon the idea because uncertainty exists"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,50,false,true,'general',true,405) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('6abfe606-03ef-56ff-821f-fb9a07442a15',1,to_jsonb(1),'A reversible, bounded test can be rational even with uncertainty because it creates information at limited downside.','Evidence thresholds should reflect stakes and reversibility.','Use AI estimates to design experiments rather than pretend uncertainty has disappeared.','{"0": "uncertainty_miscalibration", "2": "uncertainty_miscalibration", "3": "uncertainty_miscalibration"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('6abfe606-03ef-56ff-821f-fb9a07442a15','62ca3385-246b-5830-89d9-9c3d4a1947e4',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('7cef1860-fd77-578f-8b67-0370be80fca6','The chatbot request','A team says, “Our problem is that we don’t have a chatbot.” What is the best reframing?','["We need a smarter chatbot", "Competitors have chatbots", "Employees cannot get reliable policy answers quickly enough", "AI is the future"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,44,false,true,'general',true,406) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('7cef1860-fd77-578f-8b67-0370be80fca6',2,to_jsonb(2),'The first option describes the undesirable outcome without locking in a solution.','Frame the problem before choosing the mechanism.','AI should expand solution options after the actual problem is clear.','{"0": "solutioneering", "1": "solutioneering", "3": "solutioneering"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('7cef1860-fd77-578f-8b67-0370be80fca6','725d15f2-56f3-5fda-b9fe-e65fa20168f2',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('6d499a34-d778-5d4d-8fc2-5b806f91e180','The three-week recovery','A forecast says weekend shifts will recover three weeks. Which hidden assumption matters most?','["The chart will remain blue", "The forecast will fit on one slide", "People like weekends", "Extra shifts will add productive capacity without creating an offsetting bottleneck or rework"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,59,false,true,'general',true,407) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('6d499a34-d778-5d4d-8fc2-5b806f91e180',3,to_jsonb(3),'The recovery only follows if extra hours translate into net throughput rather than new constraints or rework.','Ask what must be true for the predicted benefit to happen.','AI forecasts often hide assumptions behind precise outputs; expose them explicitly.','{"0": "assumption_blindness", "1": "assumption_blindness", "2": "assumption_blindness"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('6d499a34-d778-5d4d-8fc2-5b806f91e180','04ac8495-66ab-50a7-95e0-0a6ea1cd1d00',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('fb198cb5-88e7-558c-bf0c-84c5ced0e485','The wet street','If it rains, the street gets wet. The street is wet. What can you conclude?','["Rain is one possible cause, but the evidence does not prove it rained", "It definitely rained", "It definitely did not rain", "Wet streets cannot have multiple causes"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,47,false,true,'general',true,408) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('fb198cb5-88e7-558c-bf0c-84c5ced0e485',0,to_jsonb(0),'The observation is compatible with rain but also with sprinklers, cleaning, burst pipes and other causes.','Do not reverse an implication without ruling out alternatives.','Expand compressed AI reasoning into explicit steps and test whether each inference follows.','{"1": "invalid_inference", "2": "invalid_inference", "3": "invalid_inference"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('fb198cb5-88e7-558c-bf0c-84c5ced0e485','7342926e-94ad-58c3-800d-1082188635c1',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('5eee8ddb-e885-5020-a652-d6536b6e4649','One question before the board meeting','A slide claims an AI tool delivers “35% efficiency”. You can ask one question. Which is highest value?','["Who chose the font?", "Compared with what baseline, on which tasks, and how was 35% measured?", "Can the claim be made 40% instead?", "Does the vendor have a nice website?"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,51,false,true,'general',true,409) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('5eee8ddb-e885-5020-a652-d6536b6e4649',1,to_jsonb(1),'The baseline, task scope and measurement method determine whether the claim is meaningful.','Ask questions that can change the decision.','Use AI to generate questions, then rank them by information value.','{"0": "low_value_question", "2": "low_value_question", "3": "low_value_question"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('5eee8ddb-e885-5020-a652-d6536b6e4649','aa9185f2-51d7-5072-8511-7413dcaa58c6',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('d3bbb6ea-e78e-5805-a600-229294766dec','The four witnesses','Which evidence most strongly supports the claim that a new process reduces defects?','["A sponsor says it feels better", "A vendor brochure describes success elsewhere", "A well-designed controlled comparison using a stable defect definition", "Three people say the process is easier"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,60,false,true,'general',true,410) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('d3bbb6ea-e78e-5805-a600-229294766dec',2,to_jsonb(2),'The controlled comparison directly tests the claim while reducing alternative explanations.','Evidence strength depends on design, relevance and independence—not enthusiasm.','AI can synthesise weak evidence persuasively; keep the evidence hierarchy visible.','{"0": "evidence_neglect", "1": "evidence_neglect", "3": "evidence_neglect"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('d3bbb6ea-e78e-5805-a600-229294766dec','2f70ee86-15d9-5d3c-9e3d-6ac2bcb7faf5',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('3f9f5ffd-feda-50d3-ab3d-10ef5b55a6c2','The charismatic pitch','Two proposals are equally affordable. A charismatic sponsor backs A; B has stronger replicated evidence. What should carry more weight?','["The sponsor’s seniority", "Which proposal has the better slogan", "Whichever proposal was presented first", "The replicated evidence, while still comparing both on common decision criteria"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,54,false,true,'general',true,411) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('3f9f5ffd-feda-50d3-ab3d-10ef5b55a6c2',3,to_jsonb(3),'Persuasiveness and authority are not substitutes for evidence.','Compare competing arguments using the same explicit criteria.','AI can generate compelling advocacy for either side; force both onto one rubric.','{"0": "authority_bias", "1": "authority_bias", "2": "authority_bias"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('3f9f5ffd-feda-50d3-ab3d-10ef5b55a6c2','27c3086c-1cb6-5695-ad57-139002ab13db',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('8e7c9cf5-7fac-5b4d-944e-dea6227921d8','The successful pilot','A pilot hit its target. Which question most protects against premature scaling?','["What conditions in the pilot may not hold at scale?", "Can we make the success slide more exciting?", "Who should announce the rollout?", "Can the target be raised after the fact?"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,58,false,true,'general',true,412) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('8e7c9cf5-7fac-5b4d-944e-dea6227921d8',0,to_jsonb(0),'A pilot can succeed under conditions that disappear at scale.','Search for boundary conditions and disconfirming evidence before closing the decision.','Ask AI to identify where its recommendation could fail, not just why it could work.','{"1": "premature_closure", "2": "premature_closure", "3": "premature_closure"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('8e7c9cf5-7fac-5b4d-944e-dea6227921d8','55f6fc56-0a05-5326-b3cb-3c15da2a86f6',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('d9f8bc17-f005-5951-aac6-99d468b4d390','Dinner plan vs payroll rule','AI gives a dinner suggestion and a payroll instruction affecting 2,000 people. Why should the second answer face more verification?','["Payroll answers are always longer", "The potential harm, scale and accountability are much higher", "Dinner choices never matter to anyone", "AI uses a different font for payroll"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,57,false,true,'general',true,413) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('d9f8bc17-f005-5951-aac6-99d468b4d390',1,to_jsonb(1),'Verification should rise with consequence, irreversibility and accountability.','Trust is context-dependent, not a fixed property of the model.','Put stronger human and source controls around higher-stakes AI uses.','{"0": "trust_boundary_error", "2": "trust_boundary_error", "3": "trust_boundary_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('d9f8bc17-f005-5951-aac6-99d468b4d390','8750eb1c-de35-5e11-909d-d35ae5b29033',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('30bdc9fb-0d5d-544e-9026-def1992c9002','The oddly precise statistic','AI states “industry error rates average 17.4%” with no citation. What is the strongest response?','["Trust it because 17.4% sounds precise", "Round it to 17% and use it", "Treat it as unsupported until a credible source can be checked", "Ask AI to repeat the number twice"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,55,false,true,'general',true,414) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('30bdc9fb-0d5d-544e-9026-def1992c9002',2,to_jsonb(2),'Precision can make fabrication more convincing; it does not create provenance.','Specific numbers should be traceable to evidence.','Require citations for consequential statistics and verify the original source.','{"0": "hallucination_acceptance", "1": "hallucination_acceptance", "3": "hallucination_acceptance"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('30bdc9fb-0d5d-544e-9026-def1992c9002','9484e8fc-32d6-58c2-a6f8-0fee42f4ebd7',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('e2802d96-49b9-564e-a228-09bbfcd4aab8','The £5m anchor','The first vendor says a project will cost £5m. A later credible benchmark says comparable work usually costs £3.2m. What bias should you guard against?','["Survivorship bias", "Hindsight bias", "Availability from recent weather", "Anchoring on the first number"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,43,false,true,'general',true,415) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('e2802d96-49b9-564e-a228-09bbfcd4aab8',3,to_jsonb(3),'The first number can pull later judgments toward it even when better evidence arrives.','Re-anchor on independent evidence, not the first salient number.','AI can inherit anchors from prompts and preceding text; reset with external benchmarks.','{"0": "anchoring", "1": "anchoring", "2": "anchoring"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('e2802d96-49b9-564e-a228-09bbfcd4aab8','0d49b8d0-94b1-597b-b3f1-ff7e746bdb0a',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('23c934a3-e7c1-5a37-9f6f-dca31e460fa7','The irreversible click','Which decision should require the strongest evidence before acting?','["Deleting the only production dataset with no backup", "Changing a reversible display preference", "Running a sandbox experiment", "Sending yourself a draft email"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,45,false,true,'general',true,416) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('23c934a3-e7c1-5a37-9f6f-dca31e460fa7',0,to_jsonb(0),'Irreversible, high-downside actions deserve a much higher evidence threshold.','Evidence thresholds should scale with downside and reversibility.','Ask AI not just “what should I do?” but “how reversible is this if wrong?”','{"1": "uncertainty_miscalibration", "2": "uncertainty_miscalibration", "3": "uncertainty_miscalibration"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('23c934a3-e7c1-5a37-9f6f-dca31e460fa7','62ca3385-246b-5830-89d9-9c3d4a1947e4',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('cfcc0c1e-a03b-517b-938a-b2c6ed27175a','The forwarded spreadsheet','A number has been copied through three spreadsheets. What most improves confidence?','["Add more decimal places", "Reconcile it to the original owned system of record", "Make the spreadsheet read-only", "Rename the tab “FINAL FINAL”"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,49,false,true,'general',true,417) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('cfcc0c1e-a03b-517b-938a-b2c6ed27175a',1,to_jsonb(1),'Provenance and reconciliation matter more than cosmetic signs of precision.','Decision-grade evidence should be attributable and traceable.','AI-generated summaries should preserve source links so claims can be audited.','{"0": "source_quality_error", "2": "source_quality_error", "3": "source_quality_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('cfcc0c1e-a03b-517b-938a-b2c6ed27175a','c3a75d64-fbae-5044-ae49-252bf3718af7',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('a7d91ae7-e243-584a-a50b-14fc2b818acd','The question that could change your mind','Which question is most diagnostic when you strongly favour a proposal?','["How can I prove I am right?", "Who already agrees with me?", "What evidence would make me change my mind?", "Can the recommendation be made shorter?"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,61,false,true,'general',true,418) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('a7d91ae7-e243-584a-a50b-14fc2b818acd',2,to_jsonb(2),'A disconfirming question actively searches for evidence your preferred view may be wrong.','Good questions challenge your own conclusion, not only competing ones.','Ask AI for the strongest evidence against your preferred answer, then inspect it seriously.','{"0": "confirmation_bias", "1": "confirmation_bias", "3": "confirmation_bias"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('a7d91ae7-e243-584a-a50b-14fc2b818acd','aa9185f2-51d7-5072-8511-7413dcaa58c6',1.0) on conflict do nothing;
insert into public.challenges(id,title,prompt,options,challenge_type,interaction_type,interaction_config,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('6aedd7bd-cfe8-5bf7-8481-463b6e31f210','The polished AI answer','An AI answer is fluent, detailed and confident. What does that tell you about whether it is correct?','["It is probably correct because detail signals expertise", "It is definitely wrong because AI wrote it", "The answer is correct if it contains headings", "Very little by itself; fluency is not evidence"]'::jsonb,'story_mcq','single_choice','{}'::jsonb,40,false,true,'general',true,419) on conflict(id) do update set title=excluded.title,prompt=excluded.prompt,options=excluded.options,challenge_type=excluded.challenge_type,interaction_type=excluded.interaction_type,difficulty=excluded.difficulty,is_published=excluded.is_published,sort_order=excluded.sort_order;
insert into public.challenge_answer_keys(challenge_id,correct_index,correct_answer,explanation,thinking_principle,application,error_patterns) values ('6aedd7bd-cfe8-5bf7-8481-463b6e31f210',3,to_jsonb(3),'Presentation quality can be high even when the underlying evidence or reasoning is weak.','Separate how an answer sounds from why it should be believed.','AI makes polished language cheap; verify the evidential chain.','{"0": "evidence_neglect", "1": "evidence_neglect", "2": "evidence_neglect"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,correct_answer=excluded.correct_answer,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('6aedd7bd-cfe8-5bf7-8481-463b6e31f210','55f6fc56-0a05-5326-b3cb-3c15da2a86f6',1.0) on conflict do nothing;
